export function renderWebviewRpcTypescript(manifest, operations, sidecarRoutes) {
	const lines = [
		"// <auto-generated by scripts/generate-webview-rpc-contracts.mjs>",
		`export const WEBVIEW_RPC_PROTOCOL_VERSION = ${manifest.protocolVersion} as const`,
		`export const WEBVIEW_RPC_PAYLOAD_SHAPES = ${JSON.stringify(manifest.shapes, null, "\t")} as const`,
		`export const WEBVIEW_RPC_OPERATIONS = ${JSON.stringify(operations, null, "\t")} as const`,
		`export const WEBVIEW_RPC_SIDECAR_ROUTES = ${JSON.stringify(sidecarRoutes, null, "\t")} as const`,
		"export type WebviewRpcOperation = keyof typeof WEBVIEW_RPC_OPERATIONS",
		"export type WebviewRpcSidecarRoute = (typeof WEBVIEW_RPC_SIDECAR_ROUTES)[number]",
		"export type WebviewRpcPayloadShapeMap = {",
	]
	for (const [name, shape] of Object.entries(manifest.shapes)) {
		lines.push(`\t${JSON.stringify(name)}: {`)
		for (const [field, rule] of Object.entries(shape.fields)) lines.push(`\t\t${JSON.stringify(field)}${rule.required ? "" : "?"}: ${payloadType(rule)}`)
		if (shape.allowAdditionalFields) lines.push("\t\t[key: string]: unknown")
		lines.push("\t}")
	}
	lines.push(
		"}",
		"export type WebviewRpcRequestPayload<TOperation extends WebviewRpcOperation> = WebviewRpcPayloadShapeMap[(typeof WEBVIEW_RPC_OPERATIONS)[TOperation][\"requestShape\"]]",
		"export type WebviewRpcResponsePayload<TOperation extends WebviewRpcOperation> = WebviewRpcPayloadShapeMap[(typeof WEBVIEW_RPC_OPERATIONS)[TOperation][\"responseShape\"]]",
		"export function webviewRpcOperation(service: string, method: string) { return WEBVIEW_RPC_OPERATIONS[`${service}.${method}` as WebviewRpcOperation] }",
		"export type WebviewRpcPayloadValidation = { ok: true } | { ok: false; reason: \"payload_not_object\" | \"missing_required_field\" | \"invalid_field_type\" | \"unexpected_field\"; field?: string }",
		"export function validateWebviewRpcPayload(service: string, method: string, direction: \"request\" | \"response\", value: unknown): WebviewRpcPayloadValidation {",
		"\tconst operation = webviewRpcOperation(service, method)",
		"\tconst shapeName = operation && (direction === \"request\" ? operation.requestShape : operation.responseShape)",
		"\treturn shapeName ? validateShape(shapeName, value) : { ok: true }",
		"}",
		"function validateShape(shapeName: string, value: unknown): WebviewRpcPayloadValidation {",
		"\tif (typeof value !== \"object\" || value === null || Array.isArray(value)) return { ok: false, reason: \"payload_not_object\" }",
		"\tconst shape = WEBVIEW_RPC_PAYLOAD_SHAPES[shapeName as keyof typeof WEBVIEW_RPC_PAYLOAD_SHAPES] as { fields: Record<string, { type: string; required?: boolean; shape?: string; values?: readonly string[] }>; allowAdditionalFields?: boolean } | undefined",
		"\tif (!shape) return { ok: false, reason: \"invalid_field_type\" }",
		"\tconst record = value as Record<string, unknown>",
		"\tfor (const [field, rule] of Object.entries(shape.fields)) {",
		"\t\tif (record[field] === undefined) { if (rule.required) return { ok: false, reason: \"missing_required_field\", field }; continue }",
		"\t\tconst item = record[field]",
		"\t\tif (!validPrimitive(rule.type, item) || (rule.values && !rule.values.includes(item as string))) return { ok: false, reason: \"invalid_field_type\", field }",
		"\t\tif (rule.shape) {",
		"\t\t\tconst nestedValues = Array.isArray(item) ? item : [item]",
		"\t\t\tfor (let index = 0; index < nestedValues.length; index++) {",
		"\t\t\t\tconst nested = validateShape(rule.shape, nestedValues[index])",
		"\t\t\t\tif (\"reason\" in nested) return { ok: false, reason: nested.reason, field: Array.isArray(item) ? `${field}[${index}].${nested.field || \"\"}` : `${field}.${nested.field || \"\"}` }",
		"\t\t\t}",
		"\t\t}",
		"\t}",
		"\tif (!shape.allowAdditionalFields) for (const field of Object.keys(record)) if (!(field in shape.fields)) return { ok: false, reason: \"unexpected_field\", field }",
		"\treturn { ok: true }",
		"}",
		"function validPrimitive(type: string, item: unknown) {",
		"\treturn type === \"unknown\" || (type === \"string\" && typeof item === \"string\") || (type === \"number\" && typeof item === \"number\" && Number.isFinite(item)) || (type === \"boolean\" && typeof item === \"boolean\") || (type === \"object\" && typeof item === \"object\" && item !== null && !Array.isArray(item)) || (type === \"array\" && Array.isArray(item)) || (type === \"stringArray\" && Array.isArray(item) && item.every((entry) => typeof entry === \"string\")) || (type === \"numberArray\" && Array.isArray(item) && item.every((entry) => typeof entry === \"number\" && Number.isFinite(entry))) || (type === \"booleanArray\" && Array.isArray(item) && item.every((entry) => typeof entry === \"boolean\")) || (type === \"objectArray\" && Array.isArray(item) && item.every((entry) => typeof entry === \"object\" && entry !== null && !Array.isArray(entry)))",
		"}",
	)
	return `${lines.join("\n")}\n`
}

function payloadType(rule) {
	if (rule.values) return rule.values.map(JSON.stringify).join(" | ")
	if (rule.shape && rule.type === "object") return `WebviewRpcPayloadShapeMap[${JSON.stringify(rule.shape)}]`
	if (rule.shape && rule.type === "objectArray") return `Array<WebviewRpcPayloadShapeMap[${JSON.stringify(rule.shape)}]>`
	return ({ string: "string", number: "number", boolean: "boolean", object: "Record<string, unknown>", array: "unknown[]", stringArray: "string[]", numberArray: "number[]", booleanArray: "boolean[]", objectArray: "Array<Record<string, unknown>>", unknown: "unknown" })[rule.type]
}
